import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import axios from "axios";

const UserDetails = () => {
  const { state } = useLocation();
  const { home, selectedDates } = state || {};
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: localStorage.getItem("full_name") || "",
    phone: "",
    idProof: "",
    persons: "",
  });
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [otpVerified, setOtpVerified] = useState(false);
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSendOtp = async () => {
    try {
      const response = await axios.post("http://localhost:5000/api/send-otp", {
        phone: formData.phone,
        email: localStorage.getItem("email"),
      });
      if (response.data.success) {
        setOtpSent(true);
        alert("OTP sent to your phone and email!");
      }
    } catch (err) {
      console.error("Error sending OTP:", err);
      setError("Failed to send OTP. Please try again.");
    }
  };

  const handleVerifyOtp = async () => {
    try {
      const response = await axios.post(
        "http://localhost:5000/api/verify-otp",
        {
          phone: formData.phone,
          otp,
        }
      );
      if (response.data.success) {
        setOtpVerified(true);
        alert("OTP verified successfully!");
      } else {
        setError("Invalid OTP. Please try again.");
      }
    } catch (err) {
      console.error("Error verifying OTP:", err);
      setError("Failed to verify OTP. Please try again.");
    }
  };

  const handleSubmit = async () => {
    if (!otpVerified) {
      setError("Please verify OTP before proceeding.");
      return;
    }

    const userId = localStorage.getItem("userId");
    try {
      // Proceed to payment
      const response = await axios.post("http://localhost:5000/api/order", {
        amount: home.price * selectedDates.length,
        houseId: home.id,
        userId,
      });
      const { orderId, amount, currency } = response.data;

      const script = document.createElement("script");
      script.src = "https://checkout.razorpay.com/v1/checkout.js";
      script.onload = () => {
        const options = {
          key: process.env.REACT_APP_RAZORPAY_KEY_ID,
          amount,
          currency,
          name: "NestFinder",
          description: `Payment for ${home.address} (${selectedDates.length} days)`,
          order_id: orderId,
          handler: async function (response) {
            try {
              const verifyResponse = await axios.post(
                "http://localhost:5000/api/payment/verify",
                {
                  razorpay_order_id: response.razorpay_order_id,
                  razorpay_payment_id: response.razorpay_payment_id,
                  razorpay_signature: response.razorpay_signature,
                  houseId: home.id,
                  userId,
                  amount,
                }
              );
              if (verifyResponse.data.status === "success") {
                // Save bookings for each selected date
                for (const date of selectedDates) {
                  const day = new Date(date).getDate();
                  await axios.post(`http://localhost:5000/api/bookings`, {
                    houseId: home.id,
                    day,
                    amount: home.price,
                    userId,
                    userDetails: formData,
                  });
                }
                // Send user details to owner's dashboard
                await axios.post(`http://localhost:5000/api/owner/booking`, {
                  houseId: home.id,
                  userId,
                  userDetails: formData,
                  selectedDates,
                });
                navigate(
                  `/booking-confirmation/${verifyResponse.data.bookingId}`
                );
              }
            } catch (error) {
              console.error("Payment verification failed:", error);
              setError(
                "Payment verification failed. Please try again or contact support."
              );
            }
          },
          prefill: {
            name: formData.name,
            email: localStorage.getItem("email"),
            contact: formData.phone,
          },
          theme: { color: "#3b82f6" },
        };

        const paymentObject = new window.Razorpay(options);
        paymentObject.open();
      };
      script.onerror = () => {
        setError("Razorpay SDK failed to load. Please try again.");
      };
      document.body.appendChild(script);
    } catch (error) {
      console.error("Payment initiation failed:", error);
      setError("Failed to initiate payment. Please try again.");
    }
  };

  return (
    <div
      style={{
        padding: "2rem",
        maxWidth: "500px",
        margin: "0 auto",
        backgroundColor: "#f0f0f0",
        minHeight: "100vh",
      }}
    >
      <h2 style={{ textAlign: "center", marginBottom: "1rem" }}>
        User Details
      </h2>
      {error && (
        <div
          style={{ color: "red", textAlign: "center", marginBottom: "1rem" }}
        >
          {error}
        </div>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
        <input
          type="text"
          name="name"
          value={formData.name}
          onChange={handleChange}
          placeholder="Full Name"
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
          }}
        />
        <input
          type="text"
          name="phone"
          value={formData.phone}
          onChange={handleChange}
          placeholder="Phone Number"
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
          }}
        />
        <input
          type="text"
          name="idProof"
          value={formData.idProof}
          onChange={handleChange}
          placeholder="ID Proof (e.g., Aadhaar, Passport)"
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
          }}
        />
        <input
          type="number"
          name="persons"
          value={formData.persons}
          onChange={handleChange}
          placeholder="Number of Persons"
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
          }}
        />
        {!otpSent ? (
          <button
            onClick={handleSendOtp}
            style={{
              padding: "0.5rem",
              backgroundColor: "#3b82f6",
              color: "white",
              borderRadius: "0.3rem",
              border: "none",
            }}
          >
            Send OTP
          </button>
        ) : (
          <>
            <input
              type="text"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              placeholder="Enter OTP"
              style={{
                padding: "0.5rem",
                borderRadius: "0.3rem",
                border: "1px solid #ccc",
              }}
            />
            <button
              onClick={handleVerifyOtp}
              style={{
                padding: "0.5rem",
                backgroundColor: "#3b82f6",
                color: "white",
                borderRadius: "0.3rem",
                border: "none",
              }}
            >
              Verify OTP
            </button>
          </>
        )}
        {otpVerified && (
          <button
            onClick={handleSubmit}
            style={{
              padding: "0.5rem",
              backgroundColor: "#28a745",
              color: "white",
              borderRadius: "0.3rem",
              border: "none",
            }}
          >
            Proceed to Payment
          </button>
        )}
      </div>
    </div>
  );
};

export default UserDetails;
